                tuple(grid[r][c] for c in range(bc * 6, bc * 6 + 5))
                for r in range(br * 6, br * 6 + 5)
            )
            blocks.append(block)
    counts = {}
    for block in blocks:
        counts[block] = counts.get(block, 0) + 1
    common = max(counts, key=counts.get)
    odd = next(block for block in blocks if block != common)
    return [
        [1 if odd[r][c] != common[r][c] else common[r][c] for c in range(5)]
        for r in range(5)
    ]
